import {seed,lots,tasks,assess,PARTS,KEY,TODAY,format,short} from "./domain.js";
const $=s=>document.querySelector(s);
const esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
let state;try{const saved=JSON.parse(localStorage.getItem(KEY));state=saved&&saved.version===1?{...seed(),...saved.data}:seed();}catch{state=seed();}
let modal=null,lastFocus=null;
const paths={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',layers:'<path d="m12 3 10 5-10 5L2 8zM2 12l10 5 10-5M2 16l10 5 10-5"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18m-12 4h3m3 0h3"/>',book:'<path d="M12 5c-4-3-8-2-10-1v15c3-1 6-1 10 1 4-2 7-2 10-1V4c-2-1-6-2-10 1v15"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',refresh:'<path d="M20 7v5h-5M4 17v-5h5"/><path d="M6 7a7 7 0 0 1 12-1l2 3M4 15l2 3a7 7 0 0 0 12-1"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',check:'<path d="m5 12 4 4L19 6"/>',bolt:'<path d="m13 2-8 12h6l-1 8 9-13h-7z"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',chip:'<rect x="6" y="6" width="12" height="12" rx="2"/><path d="M9 2v4m6-4v4M9 18v4m6-4v4M2 9h4m-4 6h4m12-6h4m-4 6h4"/>'};
const icon=(n)=>'<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+(paths[n]||paths.info)+'</svg>';
const badge=(text,color="gray")=>'<span class="tag '+color+'">'+esc(text)+'</span>';
const statusLabels={done:["已完成","teal"],todo:["待处理","blue"],waiting:["待确认","orange"],review:["待决策","orange"]};
function persist(){try{localStorage.setItem(KEY,JSON.stringify({version:1,data:state}));}catch{}}
function log(title,detail,kind="action"){state.events.unshift({time:state.afternoon?"15:00":"09:30",title,detail,kind});state.events=state.events.slice(0,20);state.revision++;}
function toast(text){$("#toast").textContent=text;$("#toast").classList.add("show");clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$("#toast").classList.remove("show"),3300);}
const titles={today:"今日协同",supply:"型号与批次",plan:"投料与回货",rules:"经验与规则"};
function render(){persist();const all=tasks(state),open=all.filter(t=>t.status!=="done").length;$("#app").innerHTML='<div class="shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">≋</div><div><strong>序芯</strong><small>计划与生产协同</small></div></div><div class="nav-label">工作空间</div>'+[["today","grid"],["supply","layers"],["plan","calendar"],["rules","book"]].map(([v,i])=>'<button class="nav-btn '+(state.view===v?"active":"")+'" data-nav="'+v+'">'+icon(i)+titles[v]+(v==="today"?'<span class="count">'+open+'</span>':"")+'</button>').join("")+'<div style="margin-top:31px" class="nav-label">团队 · 采购与计划</div><div style="display:flex;gap:6px;padding:0 10px">'+["陈","林","周","王","赵"].map((a,i)=>'<span class="avatar" style="width:27px;height:27px;font-size:12px;background:'+["#395068","#425b67","#4b506b","#574f64","#4c625e"][i]+';color:#dfe9f1">'+a+'</span>').join("")+'</div><div class="sidebar-bottom"><div class="nav-label" style="margin-left:0">数据来源 · 模拟</div><div class="source-line"><span><i class="dot"></i>OA 订单</span><span>08:40</span></div><div class="source-line"><span><i class="dot"></i>BI 库存</span><span>08:40</span></div><div class="source-line"><span><i class="dot" style="background:'+(state.wipUpdated?"#63d4af":"#d6af65")+'"></i>封测 WIP</span><span>'+(state.wipUpdated?"09:20":"待更新")+'</span></div><p class="sidebar-note">演示数据仅保存在本浏览器。<br>未连接真实业务系统。</p></div></aside><div class="workspace"><header class="topbar"><button class="btn ghost mobile-menu" data-action="menu" aria-label="打开导航">'+icon("menu")+'</button><div class="breadcrumb">采购与计划 <span style="padding:0 12px;color:#c0c9d6">/</span> <b>'+titles[state.view]+'</b></div><div class="top-actions"><span class="demo-pill">交互演示 · MOCK</span><span class="small-muted time-label">9 月 22 日 · '+(state.afternoon?"15:00":"09:30")+'</span><button class="btn small" data-action="advance">'+icon("clock")+(state.afternoon?"已到下午":"切换下午")+'</button><button class="btn small" data-action="guide">演示导览</button><button class="btn ghost" data-action="reset" title="重置演示" aria-label="重置演示">'+icon("refresh")+'</button><span class="avatar">陈</span></div></header><div class="page-grid"><main class="main-content" id="main">'+view()+'<div class="footer-note"><span>所有公司、型号、订单及工厂反馈均为模拟</span><span>演示日 2026.09.22 · 本浏览器状态</span></div></main>'+assistant()+'</div></div></div>';bind();renderModal();}
function heading(eyebrow,title,desc,action=""){return '<div class="page-heading"><div><div class="eyebrow">'+eyebrow+'</div><h1>'+title+'</h1><p>'+desc+'</p></div>'+action+'</div>';}
function metric(label,value,foot,color="",unit=""){return '<div class="metric"><div class="metric-label">'+label+'</div><div class="metric-value '+color+'">'+value+(unit?'<small>'+unit+'</small>':"")+'</div><div class="metric-foot">'+foot+'</div></div>';}
function view(){return state.view==="today"?today():state.view==="supply"?supply():state.view==="plan"?plan():rules();}
function today(){const all=tasks(state);let list=all.filter(t=>state.taskFilter==="all"||state.taskFilter==="fast"&&t.type.startsWith("快线")||state.taskFilter==="slow"&&t.type.startsWith("慢线")||state.taskFilter==="waiting"&&t.status==="waiting");if(state.owner!=="all")list=list.filter(t=>t.owner===state.owner);const a=assess(state,"SC6820",100000,"2026-09-25");return heading("TUESDAY / 22 SEPTEMBER",(state.afternoon?"下午好，陈悦":"早上好，陈悦"),"把计划推进，也把每一个临时交期接住。",'<button class="btn primary" data-action="wip">'+icon("refresh")+(state.wipUpdated?"WIP 已更新":"更新晨间 WIP")+'</button>')+'<div class="metrics">'+metric("今日待推进",all.filter(t=>t.status!=="done"&&t.id!=="wafer").length,"5 人协作 · 按责任人推进")+metric("工厂待确认",all.filter(t=>t.status==="waiting"&&["ft","priority"].includes(t.id)).length,state.afternoon?"确认时效已重新检查":"测试档期与急件优先级","text-orange")+metric("SC6820 交期缺口",short(a?.part==="SC6820"?a.gap:30000),"目标 9/25 · 100,000 颗","text-orange","颗")+metric("已放行可直发",state.shipped?"0":"8,000",state.received?"已核对签收，本次交付完成":state.shipped?"已交承运方，跟踪收货":"SC3215 · 青禾智能","text-teal","颗")+'</div><div class="pulse"><div class="pulse-symbol">'+icon("bolt")+'</div><div><strong>'+(state.afternoon?"下午复核：上午的确认还有效吗？":"销售急询：SC6820，周五能交 10 万颗吗？")+'</strong><p>'+(state.afternoon?"复查工厂反馈和优先级，确认不代表已经开工。":"库存、测试、封装、晶圆放在一起判断，保留每一步依据。")+'</p></div><button class="btn small accent" data-action="'+(state.afternoon?"task-ft":"assess")+'">'+(state.afternoon?"查看待确认":"查看供给与交期")+icon("arrow")+'</button></div><section class="card"><div class="card-header"><div><h2>今日任务</h2><p>固定节奏与临时需求，共用一份任务记录</p></div><select class="select small" id="owner-filter" aria-label="按负责人筛选"><option value="all">全部负责人</option>'+["陈悦","林浩","周宁","王蕾","赵宇"].map(n=>'<option '+(state.owner===n?"selected":"")+'>'+n+'</option>').join("")+'</select></div><div class="tabs">'+[["all","全部"],["fast","快线"],["slow","慢线"],["waiting","待工厂确认"]].map(([v,l])=>'<button class="tab '+(state.taskFilter===v?"active":"")+'" data-filter="'+v+'">'+l+'</button>').join("")+'</div>'+(list.length?list.map(t=>'<div class="task"><div class="priority-line '+t.priority+'"></div><div><div class="task-title">'+esc(t.title)+'</div><div class="task-meta"><span>'+t.type+'</span><span>'+t.owner+'</span><span>'+t.due+'</span></div></div><div class="task-end">'+badge(...statusLabels[t.status])+'<button class="btn small" data-task="'+t.id+'" aria-label="'+esc(t.title)+'：'+t.action+'">'+t.action+'</button></div></div>').join(""):'<div class="empty">这个筛选下没有任务</div>')+'</section><div class="two-col section-gap"><section class="card cadence"><div class="row" style="justify-content:space-between"><strong>慢线 · 固定生产节奏</strong>'+icon("calendar")+'</div><p>采购每月两次，排产每周一次，进度每天更新。</p><div class="timeline-mini"><span>9/05 采购 ✓</span><span>9/20 采购 ✓</span><span>10/05 下一轮</span></div><button class="btn ghost" style="margin-top:15px;font-size:13px" data-nav="plan">查看投料与回货 '+icon("arrow")+'</button></section><section class="card cadence"><div class="row" style="justify-content:space-between"><strong>快线 · 让确认有下文</strong>'+icon("clock")+'</div><p>急件每次确认都绑定批次、目标与有效期。到期复核，直到实际里程碑发生。</p><div class="row">'+badge("待确认","orange")+'<span style="color:#a1adbc">→</span>'+badge("已确认","blue")+'<span style="color:#a1adbc">→</span>'+badge("实际达成","teal")+'</div></section></div>';}
function supply(){const rows=lots(state).filter(l=>(state.lotFilter==="all"||l.part===state.lotFilter)&&(!state.lotSearch||[l.id,l.part,l.factory].join(" ").toLowerCase().includes(state.lotSearch.toLowerCase())));return heading("SUPPLY VISIBILITY","型号与批次","从成品库存，沿封测在制一路看到晶圆。",'<button class="btn primary" data-action="assess">测算交期 '+icon("arrow")+'</button>')+'<div class="tool-row"><div class="toolbar"><select id="part-filter" class="select" aria-label="筛选型号"><option value="all">全部型号</option>'+PARTS.map(p=>'<option value="'+p.id+'" '+(state.lotFilter===p.id?"selected":"")+'>'+p.id+' · '+p.name+'</option>').join("")+'</select></div><input type="text" id="lot-search" value="'+esc(state.lotSearch)+'" placeholder="搜索批次 / 型号 / 工厂" aria-label="搜索批次"></div><section class="card"><div class="card-header"><h2>供给全景</h2><span class="small-muted">数量口径：颗；晶圆另标折算依据</span></div><div class="table-scroll"><table><thead><tr><th>型号 / 批次</th><th>位置与工序</th><th>数量 / 已分配</th><th>预计到货</th><th>来源与依据</th></tr></thead><tbody>'+rows.map(l=>'<tr class="click-row" data-lot="'+l.id+'" tabindex="0" role="button" aria-label="查看批次 '+l.id+'"><td><strong>'+l.part+'</strong><small>'+l.id+'</small></td><td>'+l.factory+'<small>'+l.stage+'</small><div class="stage-flow" style="margin-top:9px">'+[0,1,2,3,4].map(i=>'<i class="'+(i<=l.stageIndex?"on":"")+'"></i>').join("")+'</div></td><td><strong>'+format(l.quantity)+'</strong><small>'+l.basis+' / 已分配 '+format(l.reserved)+'</small></td><td>'+l.eta.slice(5).replace("-","/")+'<small>'+(l.status==="released"?"质量已放行":l.status==="confirmed"?"工厂排期已确认":"按当前计划")+'</small></td><td><span class="small-muted">'+l.source+'</span><small>查看依据 →</small></td></tr>').join("")+'</tbody></table></div>'+(rows.length?"":'<div class="empty">没有匹配的批次</div>')+'</section><div class="notice info section-gap">供给按批次去重；已分配数量不会重复用于新的交期评估。预计良品与实测良品分别标记，完成比例不直接换算交期。</div>';}
function plan(){return heading("PLAN & EXECUTION","投料与回货","每周一份生产计划，分别跟踪下单投料与实际交付。")+'<div class="two-col"><section class="card"><div class="card-header"><h2>投料侧</h2>'+badge("本周计划","blue")+'</div><div class="card-body"><h3 style="font-size:17px">SC9102 · 新品试产</h3><p class="small-muted">5,000 颗 / 启明测试 / 目标 9/28</p><div class="notice info">测试程序已准备；发料交接与加工受理分别记录。</div><button class="btn primary section-gap" data-task="npi">'+(state.release?"查看投料结果":"查看并模拟投料")+'</button></div></section><section class="card"><div class="card-header"><h2>回货侧</h2>'+badge(state.received?"已收货":state.shipped?"已发出":"可直发",state.received?"teal":state.shipped?"blue":"teal")+'</div><div class="card-body"><h3 style="font-size:17px">SC3215 · 青禾智能</h3><p class="small-muted">8,000 颗 / FT-0918 / 质量已放行</p><div class="notice teal">按订单由测试厂直发客户，关联发运与收货证据。</div><button class="btn primary section-gap" data-task="ship">'+(state.shipped?"核对收货":"查看并模拟直发")+'</button></div></section></div><section class="card section-gap"><div class="card-header"><div><h2>本周批次计划</h2><p>计划基线 9/21 · 投料、加工与回货分别跟踪</p></div></div><div class="table-scroll"><table><thead><tr><th>批次</th><th>投料 / 加工安排</th><th>预计客户到货</th><th>跟进重点</th></tr></thead><tbody>'+lots(state).filter(l=>["FT-0920","AS-0917","AS-0919","NP-0922"].includes(l.id)).map(l=>'<tr class="click-row" tabindex="0" role="button" aria-label="查看批次 '+l.id+'" data-lot="'+l.id+'"><td><strong>'+l.id+'</strong><small>'+l.part+'</small></td><td>'+l.factory+'<small>'+l.stage+'</small></td><td>'+l.eta.slice(5).replace("-","/")+'</td><td><span class="small-muted" style="white-space:normal;display:block;min-width:150px">'+l.note+'</span></td></tr>').join("")+'</tbody></table></div></section><section class="card section-gap"><div class="card-header"><h2>晶圆采购节奏</h2><span class="small-muted">每月 5 日、20 日 · 演示设定</span></div><div class="card-body"><div class="row" style="justify-content:space-between"><div><strong>下一轮：10 月 5 日</strong><p class="small-muted">根据净需求、可用库存与已有在制形成建议。</p></div><button class="btn" data-task="wafer">查看采购建议</button></div></div></section>';}
function rules(){return heading("SHARED KNOW-HOW","经验与规则","把判断依据留下来，让同样的情况能够被一致处理。")+'<section class="card">'+[["可用量先扣分配","成品库存 30,000 颗中，10,000 颗已给其他订单预留。新询期只能使用剩余 20,000 颗。","数量校验"],["交期按剩余路线计算","排队、加工、跨厂运输、终测与质量放行分别计入。工序完成 80% 不等于剩余周期 20%。","交期依据"],["工厂确认有有效期","关键批次上午确认后，下午 15:00 复核；若优先级发生变化，立即重新确认。该时点为演示规则。","工厂协同"],["急件必须看到其他订单的影响","AS-0917 加急使用华成封装共享资源，可能让 SC3215 的 20,000 颗从 9/25 推迟到 9/28。","资源取舍"],["确认与实际进度分别验收","工厂回复“可以安排”只更新确认记录；实际开测、完工和签收需要各自的证据。","完成条件"]].map(([t,d,tag],i)=>'<div class="rule"><div class="rule-number">0'+(i+1)+'</div><div><h3>'+t+'</h3><p>'+d+'</p>'+badge(tag,"gray")+' <span class="small-muted">演示规则 v1 · 待企业核定</span></div></div>').join("")+'</section>';}
function assistant(){return '<aside class="assistant"><section class="card"><div class="card-header"><div class="assistant-heading"><div class="spark">✧</div><h2>协同助手</h2></div>'+badge("场景模拟","teal")+'</div><div class="assistant-body"><p class="assistant-greeting">我会把分散的进度整理成判断，并把未解决的条件留成待办。</p><button class="suggestion" data-prompt="SC6820 周五到货 10 万颗，能满足吗？">SC6820 周五能到货 10 万颗吗？<small>库存 → 封测在制 → 晶圆</small></button><button class="suggestion" data-prompt="今天有哪些批次需要催办？">今天哪些批次需要催办？</button><div class="chat-messages">'+state.messages.map(m=>'<div class="chat-bubble '+(m.role==="user"?"user":"")+'">'+esc(m.text)+'</div>').join("")+'</div><form id="chat-form" class="assistant-input"><textarea id="chat-input" aria-label="输入演示指令" placeholder="试试：查看 SC6820，或查看今日待办"></textarea><div class="input-footer"><span>Enter 发送 · Shift + Enter 换行</span><button class="send" aria-label="发送">↑</button></div></form></div><div class="assistant-note">预设场景 + 规则测算，未连接大模型。<br>模拟操作不会发送消息或修改真实订单。</div></section><section class="feed"><div class="eyebrow" style="margin:0 0 18px 5px">协同动态</div>'+state.events.slice(0,4).map(e=>'<div class="feed-item"><strong><span class="feed-time">'+e.time+'</span>'+esc(e.title)+'</strong><p>'+esc(e.detail)+'</p></div>').join("")+'</section></aside>';}
function assessmentHTML(a){return '<div class="assessment-top"><div class="row" style="justify-content:space-between"><h3>'+a.part+' · '+format(a.quantity)+' 颗</h3>'+badge(a.gap?"有交付缺口":a.expected?"有条件覆盖":"现货可覆盖",a.gap?"orange":a.expected?"blue":"teal")+'</div><p>客户到货日期 '+a.date+' · 数量均按颗计 · 评估不占用库存</p><div class="coverage"><span class="coverage-stock" style="width:'+a.stock/a.quantity*100+'%"></span><span class="coverage-expected" style="width:'+a.expected/a.quantity*100+'%"></span><span class="coverage-gap" style="width:'+a.gap/a.quantity*100+'%"></span></div><div class="summary-nums"><div><b class="text-teal">'+format(a.stock)+'</b><span>可用现货</span></div><div><b style="color:#578cad">'+format(a.expected)+'</b><span>按期预计供给</span></div><div><b class="text-orange">'+format(a.gap)+'</b><span>到期数量缺口</span></div></div></div><div class="table-scroll"><table><thead><tr><th>供给批次</th><th>未分配数量</th><th>预计到货</th><th>本次覆盖</th></tr></thead><tbody>'+a.rows.map(l=>'<tr><td><strong>'+l.id+'</strong><small>'+l.factory+' · '+l.stage+'</small></td><td>'+format(l.available)+'<small>'+l.basis+'</small></td><td>'+l.eta.slice(5).replace("-","/")+'</td><td>'+(!l.onTime?badge("晚于需求","orange"):l.use?format(l.use):"—")+'</td></tr>').join("")+'</tbody></table></div><div style="padding:18px 22px">'+(a.conditions.length?'<div class="notice"><strong>在制供给的待验证条件</strong><ul>'+a.conditions.map(c=>'<li>'+esc(c)+'</li>').join("")+'</ul></div>':'<div class="notice teal">可用库存覆盖本次需求；正式回复前仍须由有权负责人确认并预留。</div>')+'<details class="reasoning"><summary>查看交期是如何推出来的</summary><ol><li><strong>先扣除已分配。</strong>SC6820 仓库 30,000 − 已预留 10,000 = 可用于新需求 20,000 颗；按样例物流 1 天计算客户到货。</li><li><strong>沿剩余工序。</strong>测试批次正常场景：9/23 终测 → 9/24 放行出厂 → 9/25 到货。拒绝目标档期时，预计到货改为 9/28。</li><li><strong>检查日期覆盖。</strong>封装批次正常排程 9/29 到货，不能填补 9/25 缺口；工厂接受加急后才采用 9/25 的新排程。</li><li><strong>追到晶圆。</strong>WF-0905 为独立批次，12 片按剩余路线预计得到 72,000 颗，10/13 才能形成交付。</li><li><strong>保留不确定性。</strong>厂方排期确认只消除排期条件；预计良品、质量放行和实际进度仍需后续证据。</li></ol><p>以上为固定路线与物流样例，并非按“已完成百分比”线性倒推。</p></details>'+'<p class="small-muted" style="margin:14px 0 0">来源：BI 库存、OA 分配、工厂 WIP 样例。晶圆批次与下游批次为不同实物，未重复计数。预计到货已含模拟路线中的加工、放行及运输时间。</p></div>';}

function taskDetails(id){
const t=tasks(state).find(t=>t.id===id);if(!t)return {title:"任务已结束",body:'<div class="notice info">该任务已随场景变化结束，可在协同动态查看结果。</div>',foot:'<button class="btn" data-action="close">关闭</button>'};
let title=t.title,body='<div class="row">'+badge(...statusLabels[t.status])+badge(t.type,"gray")+'</div><div class="detail-facts"><div><label>业务责任人</label><strong>'+t.owner+'</strong></div><div><label>要求时间</label><strong>'+t.due+'</strong></div></div>',foot="";
if(id==="ft"||id==="priority"){
if(id==="priority"&&state.priority==="none")return expediteDetails();
const lotId=id==="ft"?"FT-0920":"AS-0917";const e=state.evidence?.[id];body+='<div class="notice info">'+(id==="ft"?"目标：9/23 开始终测，预计良品 50,000 颗，9/25 客户到货。":"目标：AS-0917 加急，预计良品 30,000 颗，9/25 客户到货。加急共享资源将影响北辰电子 20,000 颗。")+'</div><h3 class="subheading">记录工厂反馈</h3><p class="small-muted">以下模拟一条工厂回复，结构化结论和原文一起留存。</p><form id="feedback-form"><label class="radio-option"><input type="radio" name="outcome" value="accepted" checked><span>接受目标排期<small>更新工厂确认；实际开工与良品数量仍需验证。</small></span></label><label class="radio-option"><input type="radio" name="outcome" value="conditional"><span>附条件接受，仍需跟进<small>工厂尚未给出完整可执行承诺。</small></span></label><label class="radio-option"><input type="radio" name="outcome" value="rejected"><span>'+(state.afternoon?"原优先级已被挤占 / 无法维持":"无法接受目标排期")+'<small>'+(id==="ft"?"预计到货变为 9/28，需重算缺口。":"恢复正常排程 9/29 到货，同时解除另一订单的加急挤占。")+'</small></span></label><label><span class="field-label" style="margin-top:16px">补充原文 / 说明（可选）</span><textarea class="field" id="feedback-note" rows="3" placeholder="例如：请再次确认机台档期；实际开测后补进站记录。"></textarea></label></form>'+(e?'<div class="notice teal section-gap"><strong>最近一次证据 · '+e.time+'</strong><br>'+esc(e.text)+'<br><span class="small-muted">结论：'+esc(e.outcome)+' · 演示反馈</span></div>':"")+'<p class="small-muted section-gap">“工厂已确认”与“实际已开测/完工”分别记录。未回复时保留待确认，不能视为接受。</p>';foot='<button class="btn" data-action="close">保持待确认</button><button class="btn primary" data-action="record-feedback" data-subject="'+id+'">保存模拟反馈并重算</button>';
}else if(id==="wip"){body+='<div class="notice info">把工厂进度、型号别名和内部批次关联到一起，保留发生时间与数据来源。</div><div class="table-scroll section-gap"><table><thead><tr><th>来源</th><th>检查结果</th><th>处理</th></tr></thead><tbody><tr><td>启明测试 WIP</td><td>FT-0920 尚未进站</td><td>保留测试档期确认任务</td></tr><tr><td>华成封装 WIP</td><td>AS-0917 停留 36 小时</td><td>保留 9/25 交付缺口</td></tr><tr><td>质量放行记录</td><td>FT-0918 放行 8,000 颗</td><td>进入工厂直发任务</td></tr></tbody></table></div>';foot='<button class="btn primary" data-action="wip">'+(state.wipUpdated?"复查 WIP 样例":"更新晨间 WIP")+'</button><button class="btn" data-action="assess">查看交期影响</button>';
}else if(id==="npi"){body+='<h3 class="subheading">SC9102 · 5,000 颗 · 启明测试</h3><ul class="step-list"><li>核对投料条件<small>样例物料齐备，路线已批准，测试程序 TP-9102-v2 已就绪。</small></li><li>晶圆发料 / 物料交接<small>'+(state.release?"模拟交接记录 MI-DEMO-0922 已登记。":"等待记录发料数量、批次与接收方。")+'</small></li><li>测试加工订单受理<small>'+(state.release?"模拟加工单 PO-DEMO-0922 已受理；实际开测尚待确认。":"取得加工受理结果后，转入排期确认与进度跟踪。")+'</small></li></ul><div class="notice">发料完成和订单受理不代表实际开测。该演示会分别生成两条模拟证据。</div>';foot='<button class="btn primary" data-action="release" '+(state.release?"disabled":"")+'>'+(state.release?"投料记录已保存":"模拟下单并登记发料交接")+'</button>';
}else if(id==="ship"){body+='<h3 class="subheading">FT-0918 · SC3215 · 8,000 颗</h3><div class="detail-facts"><div><label>发货路径</label><strong>启明测试 → 青禾智能</strong></div><div><label>订单分配</label><strong>8,000 颗，已全部预留</strong></div><div><label>质量状态</label><strong>终测通过 / 已放行</strong></div><div><label>预计客户到货</label><strong>9 月 24 日</strong></div></div><ul class="step-list"><li>质量放行<small>模拟放行记录 QA-0918，良品数量 8,000 颗。</small></li><li>'+(state.shipped?"已交给承运方":"等待发货交接")+'<small>'+(state.shipped?"模拟发运单 SH-DEMO-0922 已登记，尚不等于客户收到。":"由测试厂直接发往客户，无需虚构公司入库。")+'</small></li><li>'+(state.received?"已收到并核对签收证据":"等待客户签收")+'<small>'+(state.received?"实收 8,000 颗，数量一致；本次交付完成。":"只有实收数量与证据齐全，才更新交付结果。")+'</small></li></ul>';foot=state.received?'<button class="btn accent" disabled>本次交付已完成</button>':state.shipped?'<button class="btn primary" data-action="receive">模拟收到签收证据</button>':'<button class="btn primary" data-action="ship">模拟交给承运方</button>';
}else if(id==="wafer"){body+='<div class="notice info">下一采购窗口：10 月 5 日。以下为独立的 11 月需求规划样例，实际执行前需核定预测、良率与工厂周期。</div><div class="table-scroll section-gap"><table><thead><tr><th>规划项</th><th>样例数量</th><th>依据</th></tr></thead><tbody><tr><td>11 月正式订单</td><td>96,000 颗</td><td>模拟订单快照</td></tr><tr><td>冲减后的净预测</td><td>120,000 颗</td><td>已扣除转为订单的部分</td></tr><tr><td>指定结转供给 WF-0905</td><td>72,000 颗</td><td>12 片 × 预计 6,000 良品/片</td></tr><tr><td><strong>未覆盖需求</strong></td><td><strong>144,000 颗</strong></td><td>216,000 − 72,000</td></tr><tr><td><strong>建议采购</strong></td><td><strong>24 片</strong></td><td>144,000 ÷ 6,000；满足 6 片整批</td></tr></tbody></table></div><div class="notice section-gap">样例假设新采购在 11/20 前可形成供给，工厂周期尚需确认。保存建议不会下达真实订单，也不会新增可用库存。</div>';foot='<button class="btn primary" data-action="wafer" '+(state.waferPlan?"disabled":"")+'>'+(state.waferPlan?"采购建议已保存":"保存模拟采购建议")+'</button>';
}else if(id==="fttrack"){body+='<div class="notice teal">工厂已确认档期，但系统还没有实际开测证据。</div><ul class="step-list"><li>工厂排期回复已留存<small>'+esc(state.evidence?.ft?.text||"接受目标排期")+'</small></li><li>下一里程碑：9/23 实际开测<small>需要新 WIP 进站记录或开测回报，才能判定达成。</small></li><li>继续跟踪最终良品及放行<small>预计 50,000 颗仍是估计数量，不自动变为成品库存。</small></li></ul>';foot='<button class="btn" data-action="task-ft">复核工厂确认</button>';
}else if(id==="impact"){body+='<div class="notice">SC6820 加急占用共享封装资源。北辰电子 SC3215 20,000 颗原计划 9/25 到货，现预计 9/28；客户尚未接受改期。</div><ul class="step-list"><li>受影响订单：北辰电子 / SC3215<small>数量 20,000 颗，原目标 9/25。</small></li><li>供应计划已变化，客户承诺保持原记录<small>必须由负责人评估拆批、补货或沟通改期。</small></li><li>下一步：陈悦在 16:00 前处理风险答复<small>这项任务保持待决策，不能随加急成功一起自动关闭。</small></li></ul>';foot='<button class="btn" data-action="expedite">查看资源取舍</button>';
}else{body+='<p>'+esc(t.description)+'</p>';foot='<button class="btn" data-action="close">关闭</button>';}
return {title,body,foot};
}
function expediteDetails(){const base=assess({...state,priority:"none"},"SC6820",100000,"2026-09-25"),fast=assess({...state,priority:"accepted",assemblyReply:"accepted"},"SC6820",100000,"2026-09-25");return {title:"加急方案 · 看清资源取舍",body:'<div class="notice info">场景：将 AS-0917 的 30,000 颗从 9/29 提前到 9/25 到货。客户需求仍为 SC6820 100,000 颗。</div><div class="table-scroll section-gap"><table><thead><tr><th>比较项</th><th>维持原计划</th><th>拆批加急</th></tr></thead><tbody><tr><td>AS-0917 预计到货</td><td>9/29</td><td><strong>9/25</strong></td></tr><tr><td>SC6820 到期缺口</td><td>'+format(base.gap)+' 颗</td><td><strong>'+format(fast.gap)+' 颗</strong></td></tr><tr><td>北辰电子 SC3215</td><td>20,000 颗 / 9/25</td><td class="text-orange">20,000 颗 / 9/28</td></tr><tr><td>额外费用（模拟）</td><td>¥0</td><td>¥1,200</td></tr><tr><td>工厂接受情况</td><td>原计划</td><td>需要取得明确确认</td></tr></tbody></table></div><div class="notice section-gap">加急会挤占另一订单的资源。创建建议后，原批次交期保持不变；只有记录工厂接受后，才更新模拟排程。完工、良品和质量放行仍待验证。</div><p class="small-muted section-gap">若测试批次 FT-0920 也延期，单独加急封装仍无法覆盖全部需求。上表缺口会随当前反馈重新计算。</p>',foot:'<button class="btn" data-action="close">保留原计划</button><button class="btn primary" data-action="propose-priority">'+(state.priority==="none"?"创建加急确认任务":"打开加急确认任务")+'</button>'};}
function saveFeedback(subject,outcome,note=""){if(!["ft","priority"].includes(subject)||!["accepted","conditional","rejected"].includes(outcome))throw Error("无效的批次或反馈结论");if(subject==="priority"&&state.priority==="none")throw Error("请先创建加急确认任务");if(typeof note!=="string"||note.length>4000)throw Error("反馈说明应为 4,000 字以内文本");if(subject==="ft"){state.ftReply=outcome;state.ftReconfirmed=state.afternoon&&outcome==="accepted";}else{state.assemblyReply=outcome;state.priority=outcome==="accepted"?"accepted":outcome==="rejected"?"rejected":"requested";state.assemblyReconfirmed=state.afternoon&&outcome==="accepted";}state.evidence||={};const labels={accepted:"工厂接受目标排期",conditional:"附条件接受，仍待确认",rejected:"工厂无法维持目标排期"};state.evidence[subject]={outcome:labels[outcome],time:state.afternoon?"15:00":"09:30",text:labels[outcome]+(note?"；"+note:"。数量、日期及对象按本任务目标记录。")};log((subject==="ft"?"FT-0920":"AS-0917")+" 反馈已记录",labels[outcome]+(subject==="priority"&&outcome==="accepted"?"；北辰电子 20,000 颗产生 3 天延期风险。":"；实际进度与最终良品仍需验证。"));if(state.assessment)calculate(state.assessment.part,state.assessment.quantity,state.assessment.date);else calculate();modal={type:"assess"};render();return {subject,outcome,gap:state.assessment.gap,conditions:state.assessment.conditions};}

function actionExtra(name){
if(name==="record-feedback"){try{saveFeedback($("#overlay [data-subject]")?.dataset.subject,$("#feedback-form input:checked")?.value,$("#feedback-note").value.trim());toast("已保存模拟反馈、更新任务并重新测算");}catch(e){toast(e.message)}return true;}
if(name==="propose-priority"){if(state.priority==="none"){state.priority="requested";log("加急确认任务已创建","提出 AS-0917 提前至 9/25 的建议；工厂未接受前保留原交期。");}modal={type:"task",id:"priority"};render();toast("原交期尚未变化，等待记录工厂接受结果");return true;}
if(name==="release"){if(!state.release){state.release=true;log("新品投料记录已保存","SC9102 5,000 颗：模拟发料交接与测试加工受理；尚未实际开测。");}render();toast("已生成模拟发料与加工受理记录");return true;}
if(name==="ship"){if(!state.shipped){state.shipped=true;log("8,000 颗已模拟交给承运方","FT-0918 从启明测试直发青禾智能；客户收货待核对。");}render();toast("已登记模拟发出，收货任务保持待处理");return true;}
if(name==="receive"){if(state.shipped&&!state.received){state.received=true;log("直发收货已核对","模拟签收证据：实收 SC3215 8,000 颗，数量一致。");}render();toast("本次模拟交付已闭环");return true;}
if(name==="wafer"){if(!state.waferPlan){state.waferPlan=true;log("晶圆采购建议已保存","11 月规划样例建议 24 片；尚未下达采购订单。");}render();toast("已保存模拟建议，未下达真实订单");return true;}
return false;
}

function showModal(type,data={}){lastFocus=document.activeElement;modal={type,...data};renderModal();setTimeout(()=>$("#overlay button, #overlay input")?.focus(),0);}
function closeModal(){modal=null;$("#overlay").innerHTML="";document.body.style.overflow="";lastFocus?.focus?.();}
function renderModal(){if(!modal){$("#overlay").innerHTML="";document.body.style.overflow="";return;}let title="",body="",foot="",wide=false;
if(modal.type==="assess"){title="交期评估";wide=true;const a=state.assessment;body='<form id="assess-form"><div class="form-grid" style="grid-template-columns:repeat(auto-fit,minmax(150px,1fr))"><label><span class="field-label">型号</span><select class="select" name="part">'+PARTS.map(p=>'<option '+((a?.part||"SC6820")===p.id?"selected":"")+'>'+p.id+'</option>').join("")+'</select></label><label><span class="field-label">需求数量 / 颗</span><input name="quantity" type="number" min="1" max="10000000" step="1" value="'+(a?.quantity||100000)+'" required></label><label><span class="field-label">客户到货日期</span><input name="date" type="date" min="'+TODAY+'" value="'+(a?.date||"2026-09-25")+'" required></label></div><div class="row" style="justify-content:space-between;margin:16px 0"><span class="small-muted">查询及评估不会预留供给</span><button class="btn primary" type="submit">重新测算 '+icon("arrow")+'</button></div></form>'+(a?'<section class="card">'+(a.revision!==state.revision?'<div class="stale">供给或任务信息已有变化，请重新测算。</div>':"")+assessmentHTML(a)+'</section>':"");foot='<button class="btn" data-action="task-ft">确认测试档期</button><button class="btn accent" data-action="expedite">比较加急方案</button>';}
else if(modal.type==="lot"){const l=lots(state).find(l=>l.id===modal.id);title=l.id+" · "+l.part;body='<div class="row">'+badge(l.stage,"blue")+badge(l.basis)+'</div><div class="detail-facts">'+[["当前位置",l.factory],["批次数量",format(l.quantity)+" 颗"],["已分配",format(l.reserved)+" 颗"],["预计客户到货",l.eta],["数据来源",l.source],["数量口径",l.basis]].map(([k,v])=>'<div><label>'+k+'</label><strong>'+v+'</strong></div>').join("")+'</div><div class="notice info">'+l.note+'</div><ul class="step-list"><li>批次与来源已关联<small>样例保留独立批次及分配，不重复累计。</small></li><li>沿实际工序判断剩余路径<small>晶圆 → 发料 → 封装 → 终测 → 放行与交付。</small></li><li>交期与数量按证据更新<small>预计、工厂确认、实际完成分别记录。</small></li></ul>';foot='<button class="btn primary" data-action="assess">评估交期</button>';}
else if(modal.type==="reset"){title="重置这次演示？";body='<p style="font-size:14px;line-height:1.9">将清除本浏览器的模拟操作，回到 9 月 22 日上午。不会影响其他浏览器或任何真实业务数据。</p>';foot='<button class="btn" data-action="close">保留当前进度</button><button class="btn primary" data-action="confirm-reset">重置演示</button>';}
else if(modal.type==="guide"){title="用一位采购同事的一天来演示";body='<ol class="step-list"><li>上午更新 WIP<small>归集工厂进度，识别待确认与异常。</small></li><li>销售临时问交期<small>查看 SC6820 10 万颗的现货、在制与缺口。</small></li><li>补齐工厂确认，比较急件取舍<small>接受加急会影响另一张订单，实际进度仍要跟踪。</small></li><li>下午复核优先级<small>过期确认重新进入待办，避免被其他订单挤掉。</small></li><li>回到计划，处理投料与直发<small>下单、实际发出和客户收到分别记录。</small></li></ol><div class="notice info">场景、公司、规则和 Agent 回复均为模拟。可随时重置，数据仅在本浏览器保留。</div>';foot='<button class="btn primary" data-action="start-guide">从晨间 WIP 开始</button>';}
else if(modal.type==="expedite"){({title,body,foot}=expediteDetails());wide=true;}
else if(modal.type==="task"){({title,body,foot}=taskDetails(modal.id));}
else {title="任务详情";body='<div class="notice info">请选择一个业务任务。</div>';}
$("#overlay").innerHTML='<div class="overlay-backdrop"><section role="dialog" aria-modal="true" aria-label="'+esc(title)+'" class="modal '+(wide?"wide":"")+'"><div class="modal-header"><div><div class="eyebrow">序芯 · 模拟业务任务</div><h2>'+esc(title)+'</h2></div><button class="close" data-action="close" aria-label="关闭">×</button></div><div class="modal-body">'+body+'</div>'+(foot?'<div class="modal-footer">'+foot+'</div>':"")+'</section></div>';document.body.style.overflow="hidden";bindOverlay();}
function calculate(part="SC6820",quantity=100000,date="2026-09-25"){state.assessment=assess(state,part,quantity,date);persist();}
function ask(text){
text=text.trim();if(!text)return;state.messages.push({role:"user",text});let answer;
const partMatch=text.toUpperCase().match(/SC\d+/);const quantityMatch=text.match(/(\d+(?:\.\d+)?)\s*万(?:颗)?/)||text.match(/(\d[\d,]*)\s*颗/);const dateMatch=text.match(/(2026-\d{2}-\d{2})/)||text.match(/(\d{1,2})\s*[\/月]\s*(\d{1,2})/);
if(/催|待办|确认|今天/.test(text)&&!quantityMatch&&!/交期|周五/.test(text)){const due=tasks(state).filter(t=>t.status==="waiting");answer="当前有 "+due.length+" 项待跟进：\n"+due.map(t=>"· "+t.title+"（"+t.owner+" / "+t.due+"）").join("\n")+"\n在任务卡中记录工厂实际反馈；没有回复会继续保持待确认。";}
else if(partMatch&&!PARTS.some(p=>p.id===partMatch[0])){answer="演示数据中没有 "+partMatch[0]+"。可用型号为 SC6820、SC3215、SC9102；不会为未知型号编造库存或交期。";}
else if(quantityMatch&&partMatch){const q=Number(quantityMatch[1].replaceAll(",",""))*(quantityMatch[0].includes("万")?10000:1);let date=dateMatch?(dateMatch[0].startsWith("2026-")?dateMatch[1]:"2026-"+dateMatch[1].padStart(2,"0")+"-"+dateMatch[2].padStart(2,"0")):/下周五/.test(text)?"2026-10-02":/周五/.test(text)?"2026-09-25":null;if(!date){answer="已识别 "+partMatch[0]+"、"+format(q)+" 颗。还需要客户要求到货日期，例如“9/25 到货”。";}else{try{calculate(partMatch[0],q,date);const a=state.assessment;answer=a.part+" / "+format(a.quantity)+" 颗 / "+a.date+" 客户到货\n\n可用现货 "+format(a.stock)+" 颗；按当前计划预计供给 "+format(a.expected)+" 颗；到期缺口 "+format(a.gap)+" 颗。\n\n"+(a.conditions.length?a.conditions.join("；")+"。":"现货可覆盖。")+"\n评估未占用库存，也未形成对客承诺。";modal={type:"assess"};}catch(e){answer=e.message;}}}
else if(partMatch){state.view="supply";state.lotFilter=partMatch[0];answer=partMatch[0]+" 的模拟批次：\n"+lots(state).filter(l=>l.part===partMatch[0]).map(l=>"· "+l.id+"："+l.factory+" / "+l.stage+" / "+format(l.quantity)+" 颗（"+l.basis+"）").join("\n")+"\n供给全景中可查看已分配数量和来源。评估交期还需需求数量与到货日期。";}
else if(/WIP|进度|报表/i.test(text)){answer="可先更新晨间 WIP，检查华成封装和启明测试的批次。型号与批次页面保留来源时间、分配和工序。";state.view="supply";}
else{answer="这是固定业务场景演示，尚未连接大模型。你可以试试：\n· SC6820 周五到货 10 万颗，能满足吗？\n· SC6820 9/25 到货 5 万颗\n· 今天哪些批次需要催办？\n也可直接使用“测算交期”表单。";}
state.messages.push({role:"assistant",text:answer});state.messages=state.messages.slice(-8);render();$(".chat-messages")?.scrollTo(0,99999);
}
function action(name,id){if(actionExtra(name))return;if(name==="close")return closeModal();if(name==="menu")return $(".sidebar").classList.toggle("mobile-open");if(name==="reset")return showModal("reset");if(name==="confirm-reset"){state=seed();modal=null;render();return toast("已回到演示初始状态");}if(name==="guide")return showModal("guide");if(name==="start-guide"){closeModal();action("wip");return;}if(name==="wip"){if(!state.wipUpdated){state.wipUpdated=true;log("晨间 WIP 已归集","两家工厂样例已核对；FT-0920 测试档期待确认，AS-0917 正常排程无法覆盖 9/25。","source");}render();return toast("已更新 2 家工厂 WIP，来源与异常已记录");}if(name==="advance"){if(!state.afternoon){state.afternoon=true;state.ftReconfirmed=false;state.assemblyReconfirmed=false;log("已切换到下午复核","关键批次的上午确认到达复核时点，重新检查优先级与排期。");}render();return toast("现在是演示时间 15:00，查看待工厂确认任务");}if(name==="assess"){if(!state.assessment)calculate();return showModal("assess");}if(name==="task-ft")return showModal("task",{id:"ft"});if(name==="expedite")return showModal("expedite");}
function bind(){$$("[data-nav]").forEach(e=>e.onclick=()=>{state.view=e.dataset.nav;render();window.scrollTo(0,0)});$$("[data-filter]").forEach(e=>e.onclick=()=>{state.taskFilter=e.dataset.filter;render()});$$("[data-action]").forEach(e=>e.onclick=()=>action(e.dataset.action));$$("[data-task]").forEach(e=>e.onclick=()=>e.dataset.task==="delivery"?action("assess"):showModal("task",{id:e.dataset.task}));$$("[data-lot]").forEach(e=>{e.onclick=()=>showModal("lot",{id:e.dataset.lot});e.onkeydown=k=>{if(k.key==="Enter"||k.key===" "){k.preventDefault();e.click()}}});$$("[data-prompt]").forEach(e=>e.onclick=()=>ask(e.dataset.prompt));$("#owner-filter")?.addEventListener("change",e=>{state.owner=e.target.value;render()});$("#part-filter")?.addEventListener("change",e=>{state.lotFilter=e.target.value;render()});$("#lot-search")?.addEventListener("input",e=>{state.lotSearch=e.target.value;const pos=e.target.selectionStart;render();$("#lot-search")?.focus();$("#lot-search")?.setSelectionRange(pos,pos)});$("#chat-form")?.addEventListener("submit",e=>{e.preventDefault();ask($("#chat-input").value)});$("#chat-input")?.addEventListener("keydown",e=>{if(e.key==="Enter"&&!e.shiftKey){e.preventDefault();ask(e.target.value)}});}
const $$=(s)=>Array.from(document.querySelectorAll(s));
function bindOverlay(){$$("#overlay [data-action]").forEach(e=>e.onclick=()=>action(e.dataset.action));$("#assess-form")?.addEventListener("submit",e=>{e.preventDefault();const f=new FormData(e.target);try{calculate(f.get("part"),Number(f.get("quantity")),f.get("date"));render();toast("测算完成，未预留库存")}catch(err){toast(err.message)}});$(".overlay-backdrop")?.addEventListener("click",e=>{if(e.target===e.currentTarget)closeModal()});}
document.addEventListener("keydown",e=>{if(e.key==="Escape"){closeModal();$(".sidebar")?.classList.remove("mobile-open")}if(e.key==="Tab"&&modal){const nodes=$$("#overlay button:not(:disabled),#overlay input,#overlay select,#overlay textarea,#overlay a").filter(e=>e.offsetParent!==null);const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
render();

function registerPageTools(){
const context=document.modelContext;if(!context?.registerTool)return;
const lifecycle=new AbortController();window.addEventListener("pagehide",()=>lifecycle.abort(),{once:true});
const tools=[
{name:"get_demo_supply_snapshot",title:"查看模拟供给",description:"读取序芯演示中的批次、任务和数据版本；不会连接真实系统。",inputSchema:{type:"object",properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input){if(input&&Object.keys(input).length)throw Error("该工具不接受参数");return {revision:state.revision,mock:true,lots:lots(state),tasks:tasks(state),afternoon:state.afternoon};}},
{name:"assess_mock_delivery",title:"测算模拟交期",description:"基于演示供给测算数量和客户到货日期，保存评估并打开结果；不预留库存、不形成承诺。",inputSchema:{type:"object",properties:{part:{type:"string",enum:PARTS.map(p=>p.id)},quantity:{type:"integer",minimum:1,maximum:10000000},date:{type:"string",pattern:"^2026-[0-9]{2}-[0-9]{2}$"}},required:["part","quantity","date"],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||Object.keys(input).some(k=>!["part","quantity","date"].includes(k)))throw Error("无效参数");calculate(input.part,input.quantity,input.date);modal={type:"assess"};render();const {part,quantity,date,stock,expected,gap,conditions}=state.assessment;return {mock:true,part,quantity,date,stock,expected,gap,conditions};}},
{name:"record_mock_supplier_reply",title:"记录模拟工厂反馈",description:"按页面相同流程记录测试或加急批次的模拟反馈、更新任务并重新测算；不发送外部消息。加急反馈需要已存在加急确认任务。",inputSchema:{type:"object",properties:{subject:{type:"string",enum:["ft","priority"]},outcome:{type:"string",enum:["accepted","conditional","rejected"]},note:{type:"string",maxLength:4000}},required:["subject","outcome"],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||Object.keys(input).some(k=>!["subject","outcome","note"].includes(k)))throw Error("无效参数");return {mock:true,...saveFeedback(input.subject,input.outcome,input.note||"")};}}
];for(const tool of tools){try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}
}
registerPageTools();
